-- Learner state + admin answer corrections.
--
-- Schema layers: external = the /api/learner and /api/admin JSON contracts; conceptual = learner,
-- question mark, attempt stats, review state, mini test; internal = the tables/indexes below.
--
-- Naming: snake_case, plural tables. Identity: learner_id is an anonymous UUID generated by the
-- browser (no accounts yet); question_id matches api/data/questions.json ("2021-22-01").
-- Normal form: 3NF - every non-key column depends on the whole key; mini test items are split
-- from their header so per-test data is not repeated.
-- Capacity (per learner): <=600 rows each in marks/stats/review, <=100 tests x <=100 items.
-- Consistency: every write path is one transaction (READ COMMITTED); counters are updated with
-- single-statement atomic upserts, so concurrent submits cannot lose an update.

CREATE TABLE answer_overrides (
    question_id  text         PRIMARY KEY,
    answer_index smallint     NOT NULL CHECK (answer_index BETWEEN 0 AND 3),
    also_correct smallint[]   NOT NULL DEFAULT '{}',
    updated_at   timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE question_marks (
    learner_id  uuid         NOT NULL,
    question_id text         NOT NULL,
    source      text         NOT NULL CHECK (source IN ('manual', 'auto')),
    marked_at   timestamptz  NOT NULL DEFAULT now(),
    PRIMARY KEY (learner_id, question_id)
);

CREATE TABLE question_stats (
    learner_id    uuid         NOT NULL,
    question_id   text         NOT NULL,
    attempts      integer      NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    wrong         integer      NOT NULL DEFAULT 0 CHECK (wrong >= 0 AND wrong <= attempts),
    streak        integer      NOT NULL DEFAULT 0 CHECK (streak >= 0 AND streak <= wrong),
    last_wrong_at timestamptz,
    PRIMARY KEY (learner_id, question_id)
);

CREATE TABLE review_states (
    learner_id         uuid         NOT NULL,
    question_id        text         NOT NULL,
    box_level          smallint     NOT NULL CHECK (box_level BETWEEN 0 AND 5),
    due_at             date         NOT NULL,
    last_confidence    text         NOT NULL CHECK (last_confidence IN ('low', 'medium', 'high')),
    last_correct       boolean      NOT NULL,
    attempts           integer      NOT NULL CHECK (attempts >= 0),
    overconfident_miss boolean      NOT NULL,
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    PRIMARY KEY (learner_id, question_id)
);

CREATE TABLE mini_test_records (
    id          uuid         PRIMARY KEY,
    learner_id  uuid         NOT NULL,
    taken_at    timestamptz  NOT NULL,
    scope_label text         NOT NULL CHECK (char_length(scope_label) BETWEEN 1 AND 200)
);
CREATE INDEX mini_test_records_learner_taken_idx ON mini_test_records (learner_id, taken_at DESC);

CREATE TABLE mini_test_items (
    record_id       uuid        NOT NULL REFERENCES mini_test_records (id) ON DELETE CASCADE,
    position        smallint    NOT NULL CHECK (position >= 0),
    question_id     text        NOT NULL,
    selected_index  smallint    NOT NULL CHECK (selected_index BETWEEN 0 AND 3),
    correct_indexes smallint[]  NOT NULL,
    is_correct      boolean     NOT NULL,
    PRIMARY KEY (record_id, position)
);
